/* =========================================================
Канбан-доска — логика приложения
Хранение: localStorage. Перетаскивание: нативный HTML5 DnD.
========================================================= */

(() => {
"use strict";

const STORAGE_KEY = "kanban-board:v1";

/* ---------- DOM ---------- */
const boardEl = document.getElementById("board");
const cardTemplate = document.getElementById("card-template");
const columnTemplate = document.getElementById("column-template");
const addColumnBtn = document.getElementById("add-column-btn");
const resetBtn = document.getElementById("reset-btn");

const dialog = document.getElementById("card-dialog");
const form = document.getElementById("card-form");
const dialogTitle = dialog.querySelector(".dialog__title");

/* ---------- Утилиты ---------- */
const uid = () =>
"id-" + Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 8);

const PRIORITY_LABELS = {
low: "Низкий",
medium: "Средний",
high: "Высокий",
};

const DEFAULT_STATE = () => ({
columns: [
{
id: uid(),
title: "Бэклог",
cards: [
{
id: uid(),
title: "Придумать структуру доски",
desc: "Определить колонки и базовые поля карточки.",
priority: "low",
tag: "план",
},
{
id: uid(),
title: "Собрать дизайн-макеты",
desc: "",
priority: "medium",
tag: "дизайн",
},
],
},
{
id: uid(),
title: "В работе",
cards: [
{
id: uid(),
title: "Сверстать интерфейс",
desc: "HTML + CSS, тёмная тема, адаптив под мобильные.",
priority: "high",
tag: "frontend",
},
],
},
{
id: uid(),
title: "Готово",
cards: [],
},
],
});

/* ---------- Состояние ---------- */
let state = loadState();

function loadState() {
try {
const raw = localStorage.getItem(STORAGE_KEY);
if (!raw) return DEFAULT_STATE();
const parsed = JSON.parse(raw);
if (!parsed || !Array.isArray(parsed.columns)) return DEFAULT_STATE();
return parsed;
} catch (err) {
console.warn("Не удалось прочитать сохранённое состояние:", err);
return DEFAULT_STATE();
}
}

function saveState() {
try {
localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
} catch (err) {
console.warn("Не удалось сохранить состояние:", err);
}
}

const findColumn = (id) => state.columns.find((c) => c.id === id);

function findCardLocation(cardId) {
for (const column of state.columns) {
const idx = column.cards.findIndex((c) => c.id === cardId);
if (idx !== -1) return { column, index: idx, card: column.cards[idx] };
}
return null;
}

/* ---------- Рендер ---------- */
function render() {
boardEl.innerHTML = "";
state.columns.forEach((column) => boardEl.appendChild(renderColumn(column)));
}

function renderColumn(column) {
const node = columnTemplate.content.firstElementChild.cloneNode(true);
node.dataset.columnId = column.id;

const titleEl = node.querySelector(".column__title");
titleEl.textContent = column.title;
titleEl.title = "Кликните, чтобы переименовать";
titleEl.addEventListener("dblclick", () => startRenameColumn(node, column, titleEl));
titleEl.addEventListener("blur", () => commitRenameColumn(column, titleEl));
titleEl.addEventListener("keydown", (e) => {
if (e.key === "Enter") {
e.preventDefault();
titleEl.blur();
}
if (e.key === "Escape") {
titleEl.textContent = column.title;
titleEl.blur();
}
});

node.querySelector(".column__count").textContent = column.cards.length;

node.querySelector(".column__delete").addEventListener("click", () => {
if (!confirm(`Удалить колонку «${column.title}» вместе с карточками?`)) return;
state.columns = state.columns.filter((c) => c.id !== column.id);
saveState();
render();
});

node.querySelector(".column__add").addEventListener("click", () => {
openCardDialog({ columnId: column.id });
});

const list = node.querySelector("[data-dropzone]");
list.addEventListener("dragover", onDragOver);
list.addEventListener("dragleave", onDragLeave);
list.addEventListener("drop", (e) => onDrop(e, column));

column.cards.forEach((card) => {
list.appendChild(renderCard(card, column));
});

return node;
}

function renderCard(card, column) {
const node = cardTemplate.con

