});

return node;
}

function renderCard(card, column) {
const node = cardTemplate.content.firstElementChild.cloneNode(true);
node.dataset.cardId = card.id;
node.dataset.priority = card.priority || "medium";

const priorityEl = node.querySelector(".card__priority");
priorityEl.dataset.priority = card.priority || "medium";
priorityEl.textContent = PRIORITY_LABELS[card.priority] || PRIORITY_LABELS.medium;

node.querySelector(".card__title").textContent = card.title;
node.querySelector(".card__desc").textContent = card.desc || "";
node.querySelector(".card__tag").textContent = card.tag || "";

node.querySelector(".card__delete").addEventListener("click", (e) => {
e.stopPropagation();
column.cards = column.cards.filter((c) => c.id !== card.id);
saveState();
render();
});

// Редактирование по двойному клику
node.addEventListener("dblclick", () => {
openCardDialog({ columnId: column.id, cardId: card.id });
});

// Перетаскивание
node.addEventListener("dragstart", onDragStart);
node.addEventListener("dragend", onDragEnd);

return node;
}

/* ---------- Переименование колонки ---------- */
function startRenameColumn(node, column, titleEl) {
titleEl.contentEditable = "true";
titleEl.focus();
const range = document.createRange();
range.selectNodeContents(titleEl);
const sel = window.getSelection();
sel.removeAllRanges();
sel.addRange(range);
}

function commitRenameColumn(column, titleEl) {
if (titleEl.contentEditable !== "true") return;
titleEl.contentEditable = "false";
const next = titleEl.textContent.trim();
if (next && next !== column.title) {
column.title = next;
saveState();
} else {
titleEl.textContent = column.title;
}
}

/* ---------- Drag & Drop ---------- */
let draggedCardId = null;

function onDragStart(e) {
const card = e.currentTarget;
draggedCardId = card.dataset.cardId;
card.classList.add("is-dragging");
e.dataTransfer.effectAllowed = "move";
e.dataTransfer.setData("text/plain", draggedCardId);
}

function onDragEnd(e) {
e.currentTarget.classList.remove("is-dragging");
document.querySelectorAll(".column.is-drop-target").forEach((c) =>
c.classList.remove("is-drop-target")
);
draggedCardId = null;
}

function onDragOver(e) {
e.preventDefault();
e.dataTransfer.dropEffect = "move";
const columnEl = e.currentTarget.closest(".column");
if (columnEl) columnEl.classList.add("is-drop-target");
}

function onDragLeave(e) {
const columnEl = e.currentTarget.closest(".column");
const related = e.relatedTarget;
if (columnEl && related && columnEl.contains(related)) return;
if (columnEl) columnEl.classList.remove("is-drop-target");
}

function onDrop(e, targetColumn) {
e.preventDefault();
const list = e.currentTarget;
list.closest(".column")?.classList.remove("is-drop-target");

const cardId = draggedCardId || e.dataTransfer.getData("text/plain");
if (!cardId) return;

const loc = findCardLocation(cardId);
if (!loc) return;

// Уже в этой колонке — ничего не делаем
if (loc.column.id === targetColumn.id) return;

// Удаляем из исходной колонки
loc.column.cards.splice(loc.index, 1);

// Определяем индекс вставки по позиции курсора
const afterEl = getDragAfterElement(list, e.clientY);
const referenceId = afterEl?.dataset.cardId;

let insertAt = targetColumn.cards.length;
if (referenceId) {
const refIndex = targetColumn.cards.findIndex((c) => c.id === referenceId);
if (refIndex !== -1) insertAt = refIndex;
}

targetColumn.cards.splice(insertAt, 0, loc.card);
saveState();
render();
}

function getDragAfterElement(container, y) {
const cards = [...container.querySelectorAll(".card:not(.is-dragging)")];
return cards.reduce(
(closest, child) => {
const box = child.getBoundingClientRect();
const offset = y - box.top - box.height / 2;
if (offset < 0 && offset > closest.offset) {
return { offset, element: child };
}
return closest;
},
{ offset: Number.NEGATIVE_INFINITY, element: null }
).element;
}

/* ---------- Диалог карточки ---------- */
let editing = { columnId: null, cardId: null };

function openCardDialog({ columnId, car

dId = null }) {
editing = { columnId, cardId };

if (cardId) {
const loc = findCardLocation(cardId);
if (!loc) return;
dialogTitle.textContent = "Редактировать карточку";
form.elements.title.value = loc.card.title || "";
form.elements.desc.value = loc.card.desc || "";
form.elements.priority.value = loc.card.priority || "medium";
form.elements.tag.value = loc.card.tag || "";
} else {
dialogTitle.textContent = "Новая карточка";
form.reset();
form.elements.priority.value = "medium";
}

if (typeof dialog.showModal === "function") {
dialog.showModal();
} else {
dialog.setAttribute("open", "");
}

form.elements.title.focus();
}

function closeCardDialog() {
if (typeof dialog.close === "function") {
dialog.close();
} else {
dialog.removeAttribute("open");
}
}

function onSubmit(e) {
e.preventDefault();

// ВАЖНО: сохраняем target до любых операций с диалогом.
// Закрытие <dialog> и render() могут сбросить/пересоздать форму.
const formEl = e.currentTarget || form;
const getValue = (name) => {
const field = formEl.querySelector('[name="' + name + '"]');
return field ? String(field.value || "").trim() : "";
};

const data = {
title: getValue("title"),
desc: getValue("desc"),
priority: getValue("priority") || "medium",
tag: getValue("tag"),
};

if (!data.title) {
const titleField = formEl.querySelector('[name="title"]');
if (titleField) titleField.focus();
return;
}

// Целевая колонка определяется ДО render(), т.к. render() пересоздаёт DOM.
const targetColumn = editing.cardId
? null
: findColumn(editing.columnId);

if (editing.cardId) {
const loc = findCardLocation(editing.cardId);
if (loc) Object.assign(loc.card, data);
} else if (targetColumn) {
targetColumn.cards.push({ id: uid(), ...data });
} else {
console.warn("Не найдена колонка для новой карточки:", editing.columnId);
return;
}

saveState();
closeCardDialog();
render();
}

/* ---------- Колонки / сброс ---------- */
function addColumn() {
const title = prompt("Название новой колонки:", "Новая колонка");
if (title === null) return;
const clean = title.trim() || "Новая колонка";
state.columns.push({ id: uid(), title: clean, cards: [] });
saveState();
render();
// Прокрутить до новой колонки
boardEl.lastElementChild?.scrollIntoView({ behavior: "smooth", inline: "end" });
}

function resetBoard() {
if (!confirm("Сбросить доску к исходному состоянию? Все изменения будут потеряны.")) return;
state = DEFAULT_STATE();
saveState();
render();
}

/* ---------- Обработчики ---------- */
form.addEventListener("submit", onSubmit);
form.addEventListener("reset", () => setTimeout(closeCardDialog));
dialog.querySelectorAll("[data-close]").forEach((btn) =>
btn.addEventListener("click", closeCardDialog)
);
dialog.addEventListener("cancel", (e) => {
e.preventDefault();
closeCardDialog();
});

addColumnBtn.addEventListener("click", addColumn);
resetBtn.addEventListener("click", resetBoard);

// Enter на карточке (доступность) — открыть редактирование
boardEl.addEventListener("keydown", (e) => {
if (e.key !== "Enter") return;
const cardEl = e.target.closest(".card");
if (!cardEl) return;
const loc = findCardLocation(cardEl.dataset.cardId);
if (loc) openCardDialog({ columnId: loc.column.id, cardId: loc.card.id });
});

/* ---------- Старт ---------- */
render();
saveState();
})();

/* ===== Базовые переменные и сброс ===== */
:root {
--bg: #0f1220;
--bg-soft: #171b2e;
--panel: #1e2338;
--panel-2: #262c45;
--line: #2f3652;
--text: #e8ebf5;
--text-dim: #9aa3bd;
--accent: #6c8cff;
--accent-2: #8f6cff;
--danger: #ff6b6b;
--ok: #3ddc97;
--warn: #ffc857;
--low: #3ddc97;
--medium: #ffc857;
--high: #ff6b6b;
--radius: 14px;
--radius-sm: 10px;
--shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
--transition: 180ms ease;
}

* {
box-sizing: border-box;
}

html,
body {
height: 100%;
}

body {
margin: 0;
font-family: "Segoe UI", system-ui, -apple-system, "Inter", Roboto, sans-serif;
color: var(--text);
background:
radial-gradient(1200px 600px at 10% -10%, rgba(108, 140, 255, 0.18), transparent 60%),
radial-gradient(900px 500px at 110% 0%, rgba(143, 108, 255, 0.16), transparent 55%),
var(--bg);
min-height: 100vh;
display: flex;
flex-direction: column;
}

/* ===== Шапка ===== */
.app-header {
display: flex;
align-items: center;
justify-content: space-between;
gap: 16px;
padding: 18px 24px;
border-bottom: 1px solid var(--line);
backdrop-filter: blur(8px);
background: rgba(15, 18, 32, 0.6);
position: sticky;
top: 0;
z-index: 10;
flex-wrap: wrap;
}

.app-header__brand {
display: flex;
align-items: center;
gap: 12px;
}

.app-header__logo {
display: grid;
place-items: center;
width: 38px;
height: 38px;
border-radius: 11px;
background: linear-gradient(135deg, var(--accent), var(--accent-2));
font-size: 20px;
color: #fff;
box-shadow: 0 6px 18px rgba(108, 140, 255, 0.35);
}

.app-header h1 {
font-size: 20px;
margin: 0;
letter-spacing: 0.2px;
}

.app-header__actions {
display: flex;
gap: 10px;
flex-wrap: wrap;
}

/* ===== Кнопки ===== */
.btn {
border: 1px solid transparent;
border-radius: var(--radius-sm);
padding: 9px 16px;
font-size: 14px;
font-weight: 600;
font-family: inherit;
color: var(--text);
cursor: pointer;
transition: transform var(--transition), background var(--transition), border-color var(--transition), opacity var(--transition);
white-space: nowrap;
}

.btn:active {
transform: translateY(1px);
}

.btn--primary {
background: linear-gradient(135deg, var(--accent), var(--accent-2));
color: #fff;
box-shadow: 0 6px 16px rgba(108, 140, 255, 0.3);
}

.btn--primary:hover {
filter: brightness(1.08);
}

.btn--ghost {
background: var(--panel);
border-color: var(--line);
color: var(--text-dim);
}

.btn--ghost:hover {
background: var(--panel-2);
color: var(--text);
border-color: #3d466b;
}

.icon-btn {
border: none;
background: transparent;
color: var(--text-dim);
font-size: 14px;
line-height: 1;
padding: 5px 7px;
border-radius: 8px;
cursor: pointer;
transition: background var(--transition), color var(--transition);
}

.icon-btn:hover {
background: rgba(255, 107, 107, 0.14);
color: var(--danger);
}

/* ===== Доска ===== */
.board {
flex: 1;
display: flex;
gap: 16px;
align-items: flex-start;
padding: 22px 24px 40px;
overflow-x: auto;
overflow-y: hidden;
}

/* ===== Колонка ===== */
.column {
flex: 0 0 300px;
width: 300px;
max-height: calc(100vh - 140px);
display: flex;
flex-direction: column;
background: var(--panel);
border: 1px solid var(--line);
border-radius: var(--radius);
box-shadow: var(--shadow);
overflow: hidden;
transition: border-color var(--transition), box-shadow var(--transition);
}

.column.is-drop-target {
border-color: var(--accent);
box-shadow: 0 0 0 2px rgba(108, 140, 255, 0.25), var(--shadow);
}

.column__head {
display: flex;
align-items: center;
gap: 10px;
padding: 14px 14px 12px;
border-bottom: 1px solid var(--line);
}

.column__title {
font-size: 14px;
font-weight: 700;
margin: 0;
letter-spacing: 0.4px;
text-transform: uppercase;
color: var(--text);
flex: 1;
outline: none;
border-radius: 6px;
padding: 2px 4px;
}

.column__title[contenteditable="true"]:focus {
background: var(--panel-2);
}

.column__count {
min-width: 26px;
text-align: center;
padding: 2px 8px;
border-radius: 999px;
font-size: 12px;
font-weight: 700;
color: var(--text-dim);
background: var(--panel-2);
}

.column__list {
flex: 1;
overflow-y: auto;
padding: 12px;
display: flex;
flex-direction: column;
gap: 10px;
min-height: 60px;
scrollbar-width: thin;
scrollbar-color: var(--line) transparent;
}

.column__list::-webkit-scrollbar {
width: 8px;
}

.column__list::-webkit-scrollbar-thumb {
background: var(--line);
border-radius: 99px;
}

.column__list:empty::after {
content: "Перетащите сюда карточку";
display: grid;
place-items: center;
height: 70px;
border: 1.5px dashed var(--line);
border-radius: var(--radius-sm);
color: #5e6788;
font-size: 12.5px;
}

.column__add {
margin: 0 12px 12px;
}

/* ===== Карточка ===== */
.card {
background: var(--panel-2);
border: 1px solid var(--line);
border-left: 3px solid var(--medium);
border-radius: var(--radius-sm);
padding: 11px 12px 10px;
cursor: grab;
transition: transform var(--transition), border-color var(--transition), box-shadow var(--transition), opacity var(--transition);
}

.card:hover {
transform: translateY(-2px);
box-shadow: 0 8px 20px rgba(0, 0, 0, 0.28);
}

.card:focus-visible {
outline: 2px solid var(--accent);
outline-offset: 2px;
}

.card.is-dragging {
opacity: 0.45;
cursor: grabbing;
}

.card[data-priority="low"] {
border-left-color: var(--low);
}

.card[data-priority="medium"] {
border-left-color: var(--medium);
}

.card[data-priority="high"] {
border-left-color: var(--high);
}

.card__head {
display: flex;
align-items: center;
justify-content: space-between;
gap: 8px;
margin-bottom: 6px;
}

.card__priority {
font-size: 10.5px;
font-weight: 700;
letter-spacing: 0.6px;
text-transform: uppercase;
padding: 2px 8px;
border-radius: 999px;
color: var(--medium);
background: rgba(255, 200, 87, 0.12);
}

.card__priority[data-priority="low"] {
color: var(--low);
background: rgba(61, 220, 151, 0.12);
}

.card__priority[data-priority="medium"] {
color: var(--medium);
background: rgba(255, 200, 87, 0.12);
}

.card__priority[data-priority="high"] {
color: var(--high);
background: rgba(255, 107, 107, 0.12);
}

.card__title {
margin: 0 0 4px;
font-size: 14px;
font-weight: 600;
line-height: 1.35;
word-break: break-word;
}

.card__desc {
margin: 0 0 8px;
font-size: 12.5px;
line-height: 1.45;
color: var(--text-dim);
word-break: break-word;
white-space: pre-wrap;
}

.card__desc:empty {
display: none;
}

.card__meta {
display: flex;
flex-wrap: wrap;
gap: 6px;
}

.card__tag {
font-size: 11px;
font-weight: 600;
color: var(--accent);
background: rgba(108, 140, 255, 0.12);
border-radius: 6px;
padding: 2px 8px;
}

.card__tag:empty {
display: none;
}

/* ===== Диалог ===== */
.dialog {
border: 1px solid var(--line);
border-radius: var(--radius);
background: var(--panel);
color: var(--text);
padding: 0;
width: min(460px, calc(100vw - 32px));
box-shadow: var(--shadow);
}

.dialog::backdrop {
background: rgba(8, 10, 20, 0.66);
backdrop-filter: blur(3px);
}

.dialog__form {
display: flex;
flex-direction: column;
gap: 14px;
padding: 22px;
}

.dialog__title {
margin: 0;
font-size: 17px;
}

.dialog__form label {
display: flex;
flex-direction: column;
gap: 6px;
font-size: 12.5px;
font-weight: 600;
color: var(--text-dim);
}

.dialog__form input,
.dialog__form textarea,
.dialog__form select {
width: 100%;
font-family: inherit;
font-size: 14px;
color: var(--text);
background: var(--bg-soft);
border: 1px solid var(--line);
border-radius: var(--radius-sm);
padding: 10px 12px;
outline: none;
transition: border-color var(--transition), box-shadow var(--transition);
resize: vertical;
}

.dialog__form input:focus,
.dialog__form textarea:focus,
.dialog__form select:focus {
border-color: var(--accent);
box-shadow: 0 0 0 3px rgba(108, 140, 255, 0.18);
}

.dialog__actions {
display: flex;
justify-content: flex-end;
gap: 10px;
margin: 4px 0 0;
padding: 0;
}

/* ===== Адаптивность ===== */
@media (max-width: 640px) {
.app-header {
padding: 14px 16px;
}

.app-header h1 {
font-size: 17px;
}

.board {
padding: 16px 16px 32px;
}

.column {
flex: 0 0 84vw;
width: 84vw;
max-height: calc(100vh - 190px);
}
}

